"""Keep README galleries and coverage figures synchronized with the catalog."""
def generate(d,R):
 cases={c['repo']:c for c in d['cases']};s=d['stats']
 def preview(repo,title,desc):
  c=cases[repo];src=next((v['path'] for v in c['images'] if repo=='kimi-k31pro-opus55-benchmark-showcase' and 'opus-beach-golden-live.png' in v.get('original_path','')),c['cover']);return f'<a href="cases/{repo}.md"><img src="{src}" width="420" alt="{title}"></a><br><b>{title}</b><br>{desc}<br><a href="cases/{repo}.md">案例分析 →</a>' if src else f'**{title}** · 效果图待补'
 selection=[('kimi-k31pro-opus55-benchmark-showcase','黑沙滩 / 接触与时间','玄武岩的尺度、退潮薄膜与湿暗的双时钟。'),('apple-music-effect','液态标志 / 可控光学','解析曲面、边缘色散和子帧采样。'),('mg-styles-15','15种短片 / 动作语法','从装配、描线到字形变换，逐片保留节拍差异。'),('invisible-cities-opus-5.5','城市图谱 / 空间信息','城市身份稳定，布局表达不同阅读结构。'),('little-rain-cloud','雨云 / 留下痕迹','雨滴、湿图与植物回应共同建立行动反馈。'),('web-ocean','海洋 / 多尺度一致','波浪、高光、天空与泡沫如何形成同一环境。'),('csc35-diorama-day','微缩房间 / 尺度与角色','玩具屋视角、家具体量和人物需求的关系。'),('map-of-middle-earth','中土旅程 / 地形与镜头','路线、地标和事件光照组织电影旅程。'),('neon-zenith','雨夜街 / 光色因果','让招牌、地面与雨雾共享发光分布。'),('electromagnetism','交互仪表 / 操作可解释','三维场、仪表与二维曲线连接同一操作。'),('dopa-drill','学习反馈 / 感官强度','局部错误提示与逐级音画，保留可操作目标。'),('gsap-threejs-codrops','列表到详情 / 对象连续','同一视觉对象保留起点和身份。')]
 lines=['<div align="center">','', '# Design Card Atlas', '', '**Cinematic worlds. Interactive interfaces. Explainable design decisions.**','', '从真实项目的代码、画面和失败条件中，归纳帮助模型与创作者做设计决策的卡片。','',f"**{s['cards']} 子卡 · {s['patterns']} 主卡 · {s['cases']} 案例 · {s['lenses']} 专业视角 · {s['trajectories']} 设计轨迹**",'', '[浏览卡库](index.html) · [全部案例](docs/CASES.md) · [完整效果图索引](docs/CASE_GALLERY.md) · [来源审计](docs/SOURCE_AUDIT.md)','', '</div>','','![Design Card Atlas interface](assets/atlas-preview.png)','','## 它如何帮助设计','','卡片围绕具体决策组织：如何让建筑先有可读轮廓，如何让材料粗糙度和湿润程度各自表达，如何让镜头停下来读出物件，如何让导航动画保留对象身份。每个动作连接源码、案例画面、成立条件、失败模式和最小对照。','','**Movie** 判断编排镜头中的构图、尺度、材料、节奏与连续性；**Frontend** 另外判断自由观察、输入、返回、打断、可读性与状态一致性。模型署名和混合模型分工保留为来源信息，不作为质量得分。','','## 效果与案例','','图像是作者图、历史截图、线上观察或本地影片静帧；具体类型、版本边界和来源写在案例中。静帧展示不等于连续运动、物理正确性或性能验收。','', '<table>']
 for i in range(0,len(selection),2):lines += ['<tr>']+[f'<td width="50%" valign="top">{preview(*row)}</td>' for row in selection[i:i+2]]+['</tr>']
 lines += ['</table>','',f"全部 **{s['cases']}** 个来源都有案例档案；**{s['illustrated_cases']}** 个已有可展示的效果/界面图，共 **{s['visuals']}** 份观察材料。剩余条目逐项标为无独立画面、未补图或仅有宣传参考，不用假图填充。[查看全部图文案例](docs/CASE_GALLERY.md)。",'','## 从专业视角重新看一张图','','| 视角 | 要问的问题 |','|---|---|']
 for l in d['lenses']:lines.append(f"| [{l['title']}](lenses/{l['id']}.md) | {l['question'].replace('|','／')} |")
 lines += ['',f"新增 **{s['expanded_cases']}** 份深入案例按“画面观察 → 因果链 → 审美决策 → 相邻方案 → 迁移顺序”展开，其余案例保留逐机制分析。视角来自跨案例阅读和[一手专业资料](docs/PROFESSIONAL_SOURCES.md)，不是已校准的审美打分体系。",'','## 抽卡与设计轨迹','','- **抽一张**：从当前问题、视角、用途和证据筛选池中取一个机制。','- **抽三张对照**：优先不同来源，用来比较做法；并不默认三个效果可以叠加。','- **收藏与导出**：导出包含条件、失败检查和源码链接的 Markdown 工作简报，补现场约束后交给模型。收藏仅保存在当前浏览器。','- **沿轨迹练习**：按有因果关系的步骤推进，每步都有检查点与停止条件。','', '| 轨迹 | 目标 | 步骤 |','|---|---|---:|']
 for t in d['trajectories']:lines.append(f"| {t['title']} | {t['brief'].replace('|','／')} | {len(t['steps'])} |")
 lines+=['','轨迹数据在 [trajectories.json](data/editorial/trajectories.json)。例如先解决雨夜街的轮廓与接地，再统一光色和湿痕，最后检查镜头与自由交互；不以增加效果数量作为完成标准。','','## 给模型的一次工作输入','','```text','目标：修复一个明确的画面或交互问题。','先读取1–3张相关卡及案例图片，列出条件与相邻方案区别。','保留当前机位、时间、随机种子和性能预算。','一次只改一组可归因变量，输出前后对照及失败检查。','分别给Movie和Frontend结论；无改善可拒绝该机制。','```','','[空白工作模板](docs/WORK_BRIEF.md) · [专业证据仍缺什么](docs/EXPERT_GAPS.md)','','## 来源范围与 Pro 推荐核对','','原有65个目录，加21个补充仓库，合计86条来源。84个是独立Git仓，2个是本地条目。Pro完整答复的 **10项主推荐 + 2项观察候选 + 2项降级作品 = 14项** 全部已克隆并核对origin；混合模型和归属争议不阻止收录。','','本库独立保存分析、图片、媒体出处和源码永久链接。参考源码继续独立管理，不把几十个上游工作树塞进卡库；[固定版本清单](data/sources.json)和恢复脚本可在新机器重新获取。合集的全部外链没有递归镜像。','','```bash','# 只预览恢复清单，不下载','python3 scripts/fetch_sources.py --dest ../design-references --pro-only','','# 确认需要这些参考仓后，获取分析对应的固定版本','python3 scripts/fetch_sources.py --dest ../design-references --pro-only --execute','```','','## 本地使用','','打开 `index.html` 即可使用，或启动静态服务器：','','```bash','python3 -m http.server 3081 --bind 127.0.0.1','# 浏览器打开 http://127.0.0.1:3081','```','','无前端依赖安装，无外部字体/CDN，图片随仓保存。修改数据后：','','```bash','python3 scripts/build.py','python3 scripts/check.py','```','','结构检查覆盖卡号、关联、永久源码指针、图片哈希和本地链接。桌面浏览器已检查筛选、抽卡、收藏、导出下载及模态框；已编写响应式样式，但本次浏览器视口覆盖未生效，移动布局尚未完成实测。','','## 内容组织','','```text','cards/                  一种操作，一张子卡；卡后附来源效果图','patterns/               跨案例共享机制及不能互换的分支','cases/                  全部案例的分析、边界与视觉材料','lenses/                 专业诊断视角','data/editorial/         新增归纳、案例、轨迹和来源审计','assets/previews/        已观察的原始图片/静帧及其哈希台账','site/                   抽卡、检索、收藏、导出界面','scripts/                构建、校验、参考源码恢复','```','','第三方图片与素材保留原权属。原创工具代码的MIT许可仅适用于 `site/` 与 `scripts/`，不覆盖第三方媒体。[引用与媒体说明](RIGHTS.md)。','']
 (R/'README.md').write_text('\n'.join(lines))
 lines=['# 全部案例效果与图文入口','','此页保留所有来源；每张图的原出处与具体边界见完整案例和媒体台账。无独立画面的库/后端不伪装成作品效果。','']
 for c in d['cases']:
  lines += [f"## [{c['repo']}](../cases/{c['repo']}.md)",'',c['summary'],'',f"{len(c['card_ids'])} 张机制卡 · {'专项分析 + 机制分析' if c['analyses'] else '机制级分析'}",'']
  if c['cover']:
   v=next(x for x in c['images'] if x['path']==c['cover']);lines += [f"![{c['repo']}](../{c['cover']})",'',v['observation'],'',f"证据：{v['kind']}。{v['scope']}",'']
  else:lines+=['**效果图状态：未补图 / 无独立画面。** 具体缺口见来源审计，不以Logo或概念图代替。','']
 (R/'docs/CASE_GALLERY.md').write_text('\n'.join(lines))
